D={
81077:("more than / less than","Compare quantias com **more than**, **less than**, **cheaper than** e **more expensive than**.",[("The bill is {{more than}} last month.","A conta é maior que a do mês passado."),("This plan is {{cheaper than}} that one.","Este plano é mais barato que aquele."),("The rent is {{due}} on Friday.","O aluguel vence na sexta."),("It costs {{less than}} ten dollars.","Custa menos de dez dólares.")],"“Less than” significa…",["mais que","menos que","igual a"],1,"Less than = menos do que."),
920011:("Verbo + preposição","Em inglês, certos verbos **sempre levam preposição**: *wait for, listen to, look for, talk about*.",[("I {{wait for}} my friend.","Espero meu amigo."),("I {{listen to}} the story.","Escuto a história."),("I {{look for}} my keys.","Procuro minhas chaves."),("We {{talk about}} the plan.","Falamos sobre o plano.")],"Complete: “I'm waiting ___ the bus.”",["to","for","at"],1,"Wait for."),
81078:("some / any","**Some** nas frases positivas e ofertas; **any** nas perguntas e negativas.",[("We need {{some}} soap.","Precisamos de sabão."),("Is there {{any}} milk?","Tem leite?"),("There isn't {{any}} juice.","Não tem suco."),("Would you like {{some}} water?","Você quer água?")],"Complete: “There isn't ___ bread.”",["some","any","a"],1,"Na negativa: any."),
81079:("will: decisões","**Will** para decisões na hora e promessas: *I'll tell you soon*. Formas curtas: **I'll, we'll**. Negativa: **won't**.",[("We {{will pack}} tonight.","Vamos arrumar as coisas hoje à noite."),("{{I'll}} tell you soon.","Eu te aviso logo."),("I {{won't}} forget.","Não vou esquecer."),("{{We'll}} send the new address.","Mandaremos o endereço novo.")],"Qual é a forma curta de “I will”?",["I'd","I'll","I's"],1,"I will = I'll."),
81080:("must / mustn't","**Must** = é obrigatório; **mustn't** = é proibido.",[("You {{must}} lock the door.","Você deve trancar a porta."),("You {{mustn't}} open it to strangers.","Você não deve abri-la a estranhos."),("A brick house is {{safe}}.","Uma casa de tijolos é segura."),("You {{must}} be careful.","Você precisa ter cuidado.")],"“You mustn't” quer dizer…",["não precisa","é proibido","é opcional"],1,"Mustn't = proibido."),
81081:("look / feel + adjetivo","Impressão = **look/feel + adjetivo** (não advérbio): *The room looks nice. It feels cozy.*",[("The room {{looks nice}}.","O quarto parece bonito."),("It {{feels very cozy}}.","É muito aconchegante."),("The curtains {{look}} colorful.","As cortinas parecem coloridas."),("The wall {{is}} yellow.","A parede é amarela.")],"Qual está certa?",["It looks nicely.","It looks nice.","It look nice."],1,"Look + adjetivo: nice."),
81082:("too + adjetivo","Reclame do tamanho com **too + adjetivo**: *too small, too tight*. Para pedir outro: *Do you have a larger size?*",[("This shirt is {{too small}}.","Esta camisa é pequena demais."),("Can I {{try on}} this shirt?","Posso experimentar esta camisa?"),("It's {{too tight}}.","Está apertada demais."),("Do you have {{a larger size}}?","Você tem um tamanho maior?")],"Complete: “These shoes are ___ big.”",["too","enough","very"],0,"Excesso: too."),
81083:("fit / enough","Caimento: **fit** (servir), **too small/big**, **big enough**.",[("This shoe {{doesn't fit}}.","Este sapato não serve."),("It is {{big enough}}.","É grande o suficiente."),("The slipper fits {{perfectly}}.","O chinelo serve perfeitamente."),("Try the {{next size}}.","Experimente o próximo tamanho.")],"Qual frase diz que é suficiente?",["It's big enough.","It's too big.","It isn't big."],0,"Enough = suficiente."),
81084:("Comparar preços","Adjetivos curtos: **-er than**. Longos: **more … than**.",[("This one is {{cheaper than}} that one.","Este é mais barato que aquele."),("That jacket costs {{more than}} fifty dollars.","Aquela jaqueta custa mais de 50 dólares."),("The quality is {{better}}.","A qualidade é melhor."),("It is {{more expensive than}} I thought.","É mais caro do que pensei.")],"Qual está certa?",["more cheap than","cheaper than","cheapest than"],1,"Cheap é curto: cheaper than."),
30038:("more … than","Adjetivos longos: **more + adjetivo + than**. O contrário: **less**. Curtos: **-er**.",[("This jacket is {{more expensive than}} that one.","Esta jaqueta é mais cara que aquela."),("The red one is {{more affordable}}.","A vermelha é mais acessível."),("That's {{overpriced}}!","Está caro demais!"),("The blue one is {{less pricey}}.","A azul é menos cara.")],"Como dizer “mais acessível”?",["more affordable","affordabler","most affordable"],0,"Affordable é longo: more affordable."),
70076:("Preço: comparar","Para comparar preços: **more … than**, **less … than** e **-er than**.",[("I {{can't afford}} it today.","Não posso pagar por isso hoje."),("{{Shop around}}. Compare the prices.","Pesquise. Compare os preços."),("This one is {{more pricey}} than that.","Este é mais caro que aquele."),("A freebie is {{cheaper than}} a sale!","Brinde é mais barato que promoção!")],"“Out of my price range” quer dizer…",["muito barato","caro demais para mim","bom preço"],1,"Está fora do meu orçamento."),
920012:("until / while / during","**Until** = até; **while** = enquanto (+ sujeito e verbo); **during** = durante (+ substantivo).",[("Wait {{until}} it is thick.","Espere até ficar grosso."),("{{While}} the sauce cooks, I sing.","Enquanto o molho cozinha, eu canto."),("Don't talk {{during}} the film.","Não converse durante o filme."),("Stir {{until}} it's ready.","Mexa até ficar pronto.")],"Complete: “Don't talk ___ the movie.”",["while","during","until"],1,"Durante + substantivo: during."),
81085:("the cheapest","Superlativo: **the + adjetivo-est**: *the cheapest, the best, the most expensive*.",[("This is {{the cheapest}} one.","Este é o mais barato."),("Everything is {{on sale}}.","Tudo está em promoção."),("You get a {{discount}} of ten percent.","Você ganha dez por cento de desconto."),("This is {{the best}} deal.","Esta é a melhor oferta.")],"Qual é o superlativo de “expensive”?",["the expensivest","the most expensive","the more expensive"],1,"Adjetivo longo: the most."),
81086:("I'd like to","Para pedir com educação: **I'd like to** + verbo. *I'd like to return this. I'd like a refund.*",[("{{I'd like to}} return this.","Gostaria de devolver isto."),("{{Do you have}} the receipt?","Você tem o recibo?"),("{{I'd like}} a refund.","Gostaria de um reembolso."),("The cup is {{broken}}.","A xícara está quebrada.")],"Complete: “I'd like ___ exchange it.”",["to","for","of"],0,"I'd like to + verbo."),
81087:("should arrive","**Should** mostra expectativa: *It should arrive on Monday.*",[("It {{should arrive}} on Monday.","Deve chegar na segunda."),("I can {{track}} my order.","Posso rastrear meu pedido."),("They offer {{free shipping}}.","Eles oferecem frete grátis."),("The package {{should}} be here soon.","O pacote deve chegar logo.")],"“It should arrive tomorrow” quer dizer…",["Chegou ontem.","Espera-se que chegue amanhã.","Não vai chegar."],1,"Should = expectativa."),
81088:("Would you like…?","Para oferecer: **Would you like…?** ou **Do you want…?** Para pagar: *by card / in cash*.",[("{{Would you like}} a bag?","Você quer uma sacola?"),("{{Do you want}} the receipt?","Quer o recibo?"),("I'll pay {{by card}}.","Vou pagar no cartão."),("The total is {{twelve dollars}}.","O total é doze dólares.")],"Qual oferta é mais educada?",["Want bag?","Would you like a bag?","You bag?"],1,"Would you like é a forma polida."),
81089:("I need to","O que é preciso: **I need to** + verbo. *I need to open an account.*",[("I {{need to}} open an account.","Preciso abrir uma conta."),("Please {{sign}} here.","Assine aqui, por favor."),("Is there a {{monthly fee}}?","Há taxa mensal?"),("I want to make a {{deposit}}.","Quero fazer um depósito.")],"Complete: “I need ___ save money.”",["to","for","at"],0,"Need to + verbo."),
81090:("if + will","Planos: **if + presente**, depois **will**. *If I save, I will buy a bike.*",[("{{If}} I save, I {{will buy}} a bike.","Se eu economizar, comprarei uma bicicleta."),("I {{put}} ten dollars in the bank.","Coloco dez dólares no banco."),("If you spend too much, you {{won't save}}.","Se gastar demais, não vai economizar."),("If it snows, we {{will stay}} in.","Se nevar, ficaremos em casa.")],"Qual está certa?",["If I will save, I buy.","If I save, I will buy.","If I saved, I will buy."],1,"If + presente, depois will."),
81091:("Pronomes de objeto","Depois de uma preposição (*for*), use **me, you, him, her, us, them**.",[("This gift is for {{her}}.","Este presente é para ela."),("Can you wrap {{it}}?","Você pode embrulhar?"),("It is {{her}} birthday.","É o aniversário dela."),("The flowers are for {{them}}.","As flores são para eles.")],"Complete: “This book is for ___.” (ele)",["he","him","his"],1,"Depois de for: him."),
920013:("phrasal verbs","*Give up, carry on, keep going.* Com pronome, o phrasal abre: **give it up**.",[("Don't {{give up}} now!","Não desista agora!"),("{{Carry on}} until the end.","Continue até o fim."),("I {{work out}} every day.","Treino todo dia."),("Don't give {{it}} up!","Não desista disso!")],"“Carry on” significa…",["desistir","continuar","começar"],1,"Carry on = continuar."),
81092:("Imperativo","Receitas começam com o **verbo base**: *Mix the eggs. Add the flour.*",[("{{Mix}} the eggs.","Misture os ovos."),("{{Add}} two cups of flour.","Acrescente duas xícaras de farinha."),("{{Bake}} for thirty minutes.","Asse por trinta minutos."),("{{Stir}} well.","Mexa bem.")],"Qual está no imperativo?",["Adding flour.","Add the flour.","You adds flour."],1,"Imperativo = verbo base."),
81093:("then, after, until","Para ordenar: **first, then, after that, until**.",[("{{First}}, chop the onion.","Primeiro, pique a cebola."),("{{Then}} fry it in oil.","Depois, frite-a no óleo."),("{{After that}}, boil the beans.","Depois disso, cozinhe o feijão."),("Stir {{until}} it's soft.","Mexa até ficar macio.")],"Qual palavra abre o passo a passo?",["Finally","First","Until"],1,"First abre a sequência."),
81094:("How many / How much","**How many** com o que se conta (*eggs*); **how much** com o que não se conta (*milk*).",[("{{How many}} eggs do you need?","Quantos ovos você precisa?"),("{{How much}} milk do you need?","De quanto leite você precisa?"),("I need two {{cups}} of flour.","Preciso de duas xícaras de farinha."),("I need {{some}} milk.","Preciso de um pouco de leite.")],"Complete: “How ___ sugar?”",["many","much","few"],1,"Açúcar não se conta: much."),
81095:("Embalagens","Use **a + embalagem + of**: *a bottle of water, a box of cereal, a can of beans, a bag of rice*.",[("I need {{a bottle of}} water.","Preciso de uma garrafa de água."),("Buy {{a box of}} cereal.","Compre uma caixa de cereal."),("We need {{a can of}} beans.","Precisamos de uma lata de feijão."),("Add {{a bag of}} rice.","Acrescente um pacote de arroz.")],"Complete: “a ___ of milk”",["box","carton","bag"],1,"Leite vem numa caixinha (carton)."),
81096:("Could we…?","Para pedir com educação: **Could we have…?** ou **Can we sit…?**",[("{{Could we have}} a table?","Poderíamos ter uma mesa?"),("We have {{a reservation}}.","Temos uma reserva."),("{{Can we sit}} outside?","Podemos sentar lá fora?"),("{{Could we}} wait here?","Podemos esperar aqui?")],"Qual é mais educado?",["We want a table.","Could we have a table?","Table!"],1,"Could we have…? é cortês."),
81097:("I'll have / I'd like","Para pedir: **I'll have** ou **I'd like** + prato.",[("{{I'll have}} the chicken.","Vou querer o frango."),("{{I'd like}} a soup.","Gostaria de uma sopa."),("{{What would you like}} to drink?","O que você gostaria de beber?"),("{{I'll have}} some water.","Vou querer água.")],"Qual frase faz um pedido?",["I'll have the soup.","I have soup.","I had soup."],0,"I'll have + prato é o pedido."),
81098:("too e but","**Too** = excesso; **but** = contraste. *It isn't hot, but it is cold. It is too cold.*",[("My soup is {{cold}}.","Minha sopa está fria."),("It is {{too}} hot.","Está quente demais."),("It's not raw, {{but}} it's cold.","Não está cru, mas está frio."),("{{Can you fix it}}?","Pode resolver isso?")],"Qual reclamação é educada?",["This is bad!","Excuse me, this is too cold.","Fix this!"],1,"Excuse me + too cold é educado."),
920014:("better, faster","Advérbios curtos ganham **-er**; longos usam **more**; *well* vira **better**.",[("Don runs {{faster than}} you.","O Don corre mais rápido que você."),("Speak {{more slowly}}.","Fale mais devagar."),("You dance {{better than}} her.","Você dança melhor que ela."),("She sings {{more beautifully}}.","Ela canta mais lindamente.")],"Qual é o comparativo de “well”?",["weller","better","more well"],1,"Well → better."),
81099:("any / no","**Any** em perguntas e negativas; **no** = nenhum.",[("I am {{vegan}}.","Eu sou vegano."),("Do you have {{any}} vegan dishes?","Vocês têm pratos veganos?"),("There is {{no}} cheese.","Não há queijo."),("I am {{allergic}} to nuts.","Sou alérgico a nozes.")],"Complete: “There is ___ meat in it.” (nenhuma)",["any","no","some"],1,"No meat = nenhuma carne."),
81100:("should","Para conselho: **should + verbo base**. *You should leave a tip.*",[("You {{should}} leave a tip.","Você deve deixar gorjeta."),("Twenty percent is {{common}}.","Vinte por cento é comum."),("You {{shouldn't}} forget.","Você não deve esquecer."),("How much do I {{owe}} you?","Quanto lhe devo?")],"“You shouldn't” indica…",["conselho contra","obrigação","convite"],0,"Shouldn't = não é bom fazer."),
81101:("bring × take","**Bring** traz algo para cá. **Take** leva algo daqui para lá.",[("Please {{bring}} some chips.","Traga batatas fritas, por favor."),("We need more {{drinks}}.","Precisamos de mais bebidas."),("{{Take}} food home.","Leve comida para casa."),("I {{made}} a big dessert.","Fiz uma sobremesa grande.")],"Complete: “Can you ___ the cake to the party?” (trazer até aqui)",["bring","take","go"],0,"Para onde estou: bring."),
81102:("have / hurt / feel","**Have** para sintomas (*a cough*); **hurt** para dor; **feel** para sensação.",[("I {{have}} a bad headache.","Estou com uma forte dor de cabeça."),("My throat {{hurts}} a lot.","Minha garganta dói muito."),("I don't {{feel}} well.","Não me sinto bem."),("She {{has}} a fever.","Ela está com febre.")],"Qual está certa?",["My head hurt.","My head hurts.","I hurts."],1,"My head (= it) pede hurts."),
81103:("on + dia / for + duração","Use **on** com o dia (*on Monday*) e **for** com duração (*for a week*).",[("I need an {{appointment}}.","Preciso de uma consulta."),("Is next {{Monday}} okay?","Segunda que vem serve?"),("Take it {{twice a day}}.","Tome duas vezes ao dia."),("Take it {{for a week}}.","Tome por uma semana.")],"Complete: “The appointment is ___ Monday.”",["in","on","at"],1,"Dia da semana: on."),
81104:("I need / how often","**I need** para pedir; **how often** para frequência.",[("{{I need}} something for a cough.","Preciso de algo para a tosse."),("{{How often}} do I take it?","Com que frequência tomo?"),("Take one pill {{after lunch}}.","Tome um comprimido depois do almoço."),("Put the cream on your hand.","Passe o creme na mão.")],"“How often?” pergunta…",["quanto custa","com que frequência","onde"],1,"How often = frequência."),
81105:("should / had better","**Should** dá conselho; **had better** é conselho forte.",[("You {{should}} drink water.","Você deveria beber água."),("You {{had better}} stay home.","É melhor você ficar em casa."),("You {{should}} sleep eight hours.","Você deveria dormir oito horas."),("You {{should}} rest.","Você deveria descansar.")],"Qual é o conselho mais forte?",["You should rest.","You had better rest.","You could rest."],1,"Had better = alerta."),
}
